def solve(g):
    h,w=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bgc=cnt.most_common(1)[0][0]
    shpc=[k for k,v in cnt.items() if k!=bgc and k!=4][:1][0]
    S={(r,c) for r in range(h) for c in range(w) if g[r][c]==shpc}
    seen=set(); q=deque()
    for r in range(h):
        for cc in(0,w-1):
            if (r,cc) not in S: seen.add((r,cc)); q.append((r,cc))
    for cc in range(w):
        for r in(0,h-1):
            if (r,cc) not in S and (r,cc) not in seen: seen.add((r,cc)); q.append((r,cc))
    while q:
        r,cc=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,cc+dc
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in S and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    target={(r,c) for r in range(h) for c in range(w) if g[r][c]==bgc and (r,c) not in seen}
    diags={(r+dr,c+dc) for (r,c) in S for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)) 
           if 0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc]==bgc}
    print('target>=diags:', target>=diags)
    return [[4 if (r,c) in target else g[r][c] for c in range(w)] for r in range(h)]
