def solve(gi, go):
    h,w=len(gi),len(gi[0])
    cnt=Counter(v for row in gi for v in row); bgc=cnt.most_common(1)[0][0]
    shpc=[k for k,v in cnt.items() if k!=bgc and k not in (4,)]
    if len(shpc)!=1: return None; shpc=shpc[0]
    S={(r,c) for r in range(h) for c in range(w) if gi[r][c]==shpc}
