        r,cc=q.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                nr,nc=r+dr,cc+dc
                if 0<=nr<h and 0<=nc<w and (nr,nc) not in W and (nr,nc) not in seen:
