    Q=set([(r,c) for r in range(h) for c in range(w) if gi[r][c]!=sset and (r==0 or r==h-1 or c==0 or c==w-1)])
    seen=set(); q=deque(Q)
    while q:
        a,b=q.popleft()
        if (a,b) in seen: continue
        seen.add((a,b))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+dr,b+dc
            if 0<=x<h and 0<=y<w and (x,y) not in Q:
                Q.add((x,y)); q.append((x,y))
    reach={(a,b) for a in range(h) for b in range(w) if (a,b) in seen}
    print(n,'changed==unreached:',od=={(r,c) for r in range(h) for c in range(w) if (r,c) not in sset and (r,c) not in reach})

