    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(gi):
    h,w=len(gi),len(gi[0]); b=Counter(v for row in gi for v in row).most_common(1)[0][0]
    seen=set(); dq=deque()
    for r in range(h):
        for c in (0,w-1):
            if gi[r][c]==b and (r,c) not in seen: seen.add((r,c)); dq.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if gi[r][c]==b and (r,c) not in seen: seen.add((r,c)); dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and gi[nr][nc]==b and (nr,nc) not in seen:
                seen.add((nr,nc)); dq.append((nr,nc))
    o=[row[:] for row in gi]
    for r in range(h):
        for c in range(w):
            if gi[r][c]==b and (r,c) not in seen: o[r][c]=4
    return o
